NOVEL_BATCH = [
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个破丹系统，要求失败中藏成功、有代价。",
  "output":"【系统名】破丹系统\n【核心功能】宿主炼丹炸炉时，可激发药性极致，炼出「破丹」——品质远超稳火丹。\n【规则】①必须真的炸炉才触发，假炸无效；②破丹品质与炸炉的「时机」挂钩；③破丹术需宿主领悟「破而后立」。\n【限制/代价】①炸炉有真实损失（药材可能全毁）；②破丹概率低，十炸九败；③破丹虽强，但「破」性伤身，服用者需承受药性冲击。\n【成长线】从「为救母炸炉」到「掌控破丹时机」，最终明白失败是另一条路的起点。\n【爽点来源】「炸炉炸出极品丹」的反差+「破而后立」的匠心。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个鉴宝神瞳的代价机制，要求异能有盲区。",
  "output":"【异能】鉴宝神瞳\n【核心功能】看穿物件真伪与年代。\n【关键盲区】①只能看「物」，不能看「人」——看不出物件背后的人心算计；②只能断真伪年代，不能断「价值」——价值需宿主懂行情；③对「人心炼制的假物」无效（如用邪术伪造的「真品」）。\n【代价】每次使用耗神，连续用头痛；看穿「因果缠身之物」会沾染因果。\n【叙事作用】神瞳不是全知——宿主常因「只看物不看人」吃亏，比如买到真品却中了卖家的局。\n【爽点来源】「看穿真伪」的专业+「盲区吃亏」的张力。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个情绪共情系统的负担机制。",
  "output":"【异能】共情\n【核心功能】读到他人情绪。\n【负担机制】①读到的情绪会「感染」宿主——读到恶意会愤怒，读到悲伤会低落；②无法关闭，走在人群里被无数情绪淹没；③读得越深，感染越重。\n【限制】①只能读情绪，不能读「想法」，易误判；②对「无情绪者」（如傀儡）无效；③过度使用会情绪崩溃。\n【成长线】宿主从「被情绪淹没」到「学会筛选与守护」，在黑暗里找光。\n【爽点来源】「看穿人心」的新鲜+「情绪负担」的真实代价。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个命运之轮的代价机制，要求逆转有取舍。",
  "output":"【金手指】命运之轮\n【核心功能】逆转一次命运（躲过危机）。\n【代价机制】①逆转次数有限（如3次）；②次数用尽后，再逆转需「抹去一段命运」——让未来某个片段永不发生；③抹去的片段由不得宿主选，可能是最珍贵的（如与某人的相遇）。\n【限制】①只能逆转「危机」，不能逆转「选择」；②逆转后危机以另一种形式回来（命运守恒）；③过度依赖会失去更多。\n【叙事作用】逼宿主权衡「保命」与「珍贵」，最终选择靠自己而非抹去珍贵。\n【爽点来源】「逆转命运」的爽+「代价取舍」的揪心。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个空白卡的灵魂负荷机制。",
  "output":"【金手指】空白卡（吞噬进化）\n【核心功能】吞噬其他卡牌继承技能，集齐解锁形态。\n【灵魂负荷机制】①每张被吞的卡残留原主人「印记」；②吞得越多印记越躁，达临界触发「反噬」；③反噬时印记争夺宿主意识。\n【限制】①不能无限吞，需定期「安抚」印记；②吞噬有「相性」，冲突的卡会互斥；③高阶卡的印记更强，难驾驭。\n【成长线】宿主从「贪吞」到「学会驾驭与平衡」，明白吞噬不是掠夺是理解。\n【爽点来源】「吞噬进化」的爽+「灵魂负荷」的紧张。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个人生模拟器的偏移机制。",
  "output":"【系统名】人生模拟器\n【核心功能】模拟未来人生，提取能力带回现实。\n【偏移机制】①模拟基于「当前轨迹」，宿主一旦改变现实，模拟就偏移失效；②改变越大，偏移越快；③模拟的「成功」不等于现实成功。\n【代价】①每次模拟消耗寿元/积分；②过度依赖会忽略真实努力；③模拟有「盲区」，给不了全知。\n【成长线】宿主从「依赖模拟趋吉避凶」到「模拟只是参考，人生自己走」。\n【爽点来源】「预知人生」的新鲜+「偏移失效」的危机。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个气运签到的偿还机制。",
  "output":"【系统名】气运签到系统\n【核心功能】签到获奖励，但奖励是预支未来气运。\n【偿还机制】①每次签到所得皆为预支；②累计百次需开始偿还；③偿还方式是随机剥夺已拥有之物（项目/合伙人/健康）。\n【限制】①剥夺不可逆；②越想保住越被剥夺；③宿主享受红利时不知代价，百次后债主上门。\n【叙事作用】前期躺赢爽，后期偿还虐，制造「出来混迟早要还」的张力。\n【爽点来源】「签到躺赢」的爽+「气运偿还」的反转。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个败家系统的吸收机制，要求系统有黑暗真相。",
  "output":"【系统名】神豪败家系统\n【核心功能】每月须花光额度，否则扣寿命。\n【黑暗真相】①败家失败的宿主，会被系统「吸收」，成为系统的一部分；②系统是「牢笼」，困住一个个宿主；③系统里藏着上一任宿主的意识。\n【规则】①额度须真实消费；②花不完扣寿命；③败家失败九十九次，第一百次就被吸收。\n【叙事作用】喜剧外壳下藏着黑暗内核——宿主以为的福利，其实是牢笼。\n【爽点来源】「求亏反赚」的喜剧+「系统真相」的反转。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个选择系统的因果链机制。",
  "output":"【系统名】选择系统\n【核心功能】给选项，选对获奖励。\n【因果链机制】①每个选项背后藏着「因果链」小字，宿主常忽略；②选某个选项会触发不可控的后续因果；③「选对」不是单纯好坏，是权衡代价。\n【限制】①选项不给「必胜」，选错自己承担；②因果链一旦触发不可撤销；③系统不替宿主判断。\n【成长线】宿主从「无脑选奖励高的」到「看清每个选择的重量」。\n【爽点来源】「选择逆袭」的爽+「因果陷阱」的张力。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个规则博弈系统的进化机制。",
  "output":"【系统名】美食续命系统（规则博弈型）\n【核心设定】系统是合同非许愿机，宿主每天须打卡续命。\n【进化机制】①宿主钻漏洞，系统打补丁；②系统会「学习」宿主的小聪明，精准封死；③系统升级出陷阱任务。\n【留漏洞】初期规则模糊（如「到店」定义），宿主研究空子，系统发现后更新条款。\n【终极代价】宿主发现打卡的店都与失踪亲人有关——系统是引导他入局的寄生。\n【爽点来源】规则博弈的智力快感+真相揭开的格局升华。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个情绪滤镜系统的误导机制。",
  "output":"【系统名】情绪价值系统\n【核心功能】看到他人头顶情绪数值。\n【误导机制】①只显示情绪类型和数值，不显示原因；②宿主常误读（如喜悦值80以为爱他，实际是新买的包）；③信息有盲区。\n【规则】①数值实时变化；②可耗积分短暂看来源，但积分难得；③过度依赖数值忽略真实沟通。\n【叙事作用】系统是滤镜非全知旁白，宿主因系统犯错比因系统无敌更有戏。\n【爽点来源】「看穿情绪」的新鲜+「误读情绪」的戏剧张力。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个反向激励系统的错位机制。",
  "output":"【系统名】反向激励系统\n【核心规则】任务失败才获奖励，成功反而无奖励。\n【错位机制】①宿主实力逆天，想输都难；②为获奖被迫「求败」（如培养对手、故意亏本）；③越求败越成功。\n【内在逻辑】系统逼宿主「放下对赢的执念」，当他真不在乎输赢反而通关。\n【限制】①奖励有绝对吸引力（如续命）；②不能故意放水，系统判定「非真实努力」无效。\n【爽点来源】「想输输不了」的反差喜剧+「规则与能力错位」的荒诞。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个混沌骨金手指，要求认主有条件。",
  "output":"【金手指】混沌骨\n【核心功能】被夺至尊骨后种下的混沌骨，力量远超至尊骨。\n【认主条件】混沌骨认「心志极坚、被夺骨而不屈」者——主角被夺骨濒死却不认命，恰好契合。解释了「为何落在废物身上」。\n【限制/代价】①力量远超宿主境界，越级动用遭反噬；②混沌骨需「驯服」，初期力量不受控；③混沌骨气息暴露引来大能觊觎。\n【成长线】从「借混沌骨一击」到「驯服混沌骨」，力量与心性同步成长。\n【爽点来源】「被夺骨反得更强骨」的反差+「混沌碾压」的凌厉。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个斩运刀金手指，要求有道德约束。",
  "output":"【金手指】斩运刀\n【核心功能】斩恶人夺其气运，照出罪孽。\n【道德约束】①斩恶人夺运，斩善人损己阴德；②刀鸣照罪孽，罪越重鸣越响；③不能斩「无罪之人」，否则反噬。\n【限制】①夺来的气运需「消化」，贪多会根基不稳；②刀只能照罪，不能替宿主判断「该不该斩」；③斩运结因果，被斩者的势力会报复。\n【成长线】主角从「为恩人复仇」到「只斩恶人」，用刀守公道而非泄私愤。\n【爽点来源】「照出罪孽」的打脸+「道德约束」的分量。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个铸魂体金手指，要求匠心积累。",
  "output":"【金手指】铸魂体\n【核心功能】能让凡铁生灵，铸出有魂的兵器。\n【匠心积累】①铸魂靠「用心」，专注、情感、领悟注入器中；②需十年打铁的手稳心静为根基；③魂的强弱与铸器者的心境挂钩。\n【限制】①铸魂耗心神，过度会虚脱；②有魂兵器会「认主」，强求不得；③铸魂体暴露引来觊觎。\n【成长线】从「铸第一件有魂剑」到「以身为器」，匠心是根本。\n【爽点来源】「凡铁生灵」的惊喜+「剑灵护主」的羁绊。"},
 {"cat":"金手指系统","genre":"仙侠","instruction":"为仙侠设计一个灵植天赋，要求懂而非力。",
  "output":"【金手指】万物生长（灵植之体）\n【核心功能】听懂灵草的话，渡生机给灵草。\n【懂而非力】①灵草会「告诉」宿主病虫害在哪、需要什么；②宿主顺着灵草的意思种，自然长好；③不靠灵力催，靠理解。\n【限制】①渡生机耗自身，过度会虚弱；②灵植之体是炼丹界梦寐以求的「药引」，暴露引来杀身之祸；③只能种植，不能直接战斗。\n【成长线】从「为糊口种灵草」到「以灵植证道」，懂是根本。\n【爽点来源】「听懂灵草」的独特+「种出极品」的专业打脸。"},
 {"cat":"金手指系统","genre":"仙侠","instruction":"为仙侠设计一个续灵缝脉手艺，要求冷门独特。",
  "output":"【金手指】续灵缝脉术\n【核心功能】修复连炼器大师都修不了的灵宝，靠「懂灵脉」而非蛮力。\n【冷门独特】①失传三百年的手艺，会的人极少；②修灵宝不是接骨头，是「请灵回家」；③谁的法器不会坏？所以谁都不敢得罪他。\n【限制】①缝脉耗心神，需极高专注；②只能修「灵脉未散」的，彻底散了的修不了；③手艺暴露引来大宗门招揽或觊觎。\n【成长线】从「补锅匠」到「续灵宗师」，懂是根本。\n【爽点来源】「冷门手艺解决大难题」的反差+「请灵回家」的专业。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个重生先知金手指，要求记忆会失效。",
  "output":"【金手指】重生记忆\n【核心功能】带着未来十年记忆重生，知道关键日期、风口、谁忠谁奸。\n【失效机制】①记忆只覆盖前世经历过/听说过的，不是全知；②一旦改变历史，后续偏离记忆，先知逐渐失效（蝴蝶效应）；③记忆是信息不是能力，抓机会仍需本事本钱。\n【张力来源】先知是一次性消耗品，用一次少一次，改变越大失效越快。逼宿主把先知用在刀刃上。\n【成长线】从「依赖记忆抢占先机」到「记忆失效后靠真本事立足」。\n【爽点来源】「提前一步落子」的掌控+「记忆失效」的危机。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个控电异能，要求贴近现实成长。",
  "output":"【异能】控电\n【核心功能】操控电流——充电、感知线路、抽取/释放电能。\n【现实起步】能力初极弱，只能给电动车充电省电费（贴近外卖员主角）。这种「没用」的起步真实有代入感。\n【成长线】从「充电省电费」到「感知电路排查隐患」到「抽取电流灭火」再到「释放电能制敌」，随对电的理解加深而成长。\n【限制】①控电耗精神力，过度虚脱；②只能控已有的电，不能凭空发电；③高压电危险，越级操控反噬自身。\n【爽点来源】「废物异能其实是神技」的反差+「能力解决现实困境」的代入。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个职业系统的实践机制，要求技能需实操。",
  "output":"【系统名】职业系统（厨神/神医/律师等）\n【核心功能】发布职业任务，完成奖励技能。\n【实践机制】①技能需实操才精通，不是给了就满级；②高级技能需累计作品/治愈数/胜诉数解锁；③系统不替宿主实操，只给工具。\n【限制】①误诊/做砸/败诉扣积分；②不给「包治百病/自动做菜/必胜官司」；③技能有上限需突破。\n【成长线】从「行业底层」到「行业泰斗」，精进靠实践积累。\n【爽点来源】「专家不行我行」的专业打脸+「技能解锁」的反馈。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个经营系统的烟火气机制。",
  "output":"【系统名】经营系统（开店/种田/基建）\n【核心功能】发布经营任务，奖励资源，积累解锁升级。\n【烟火气机制】①家人围坐、邻里互助、顾客满意等日常产生「繁荣度」推动升级；②经营不只是赚钱，是「用心」与「传承」；③稳扎稳打非一步登天。\n【限制】①资源有限需取舍；②扩张引来竞争/觊觎；③拔苗助长根基不稳。\n【成长线】从「为生计经营」到「做成百年招牌」，用心是根本。\n【爽点来源】「从无到有」的积累+「烟火气」的治愈。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个声望系统的德配位机制。",
  "output":"【系统名】声望系统\n【核心功能】他人认可转化为声望值兑换奖励。\n【德配位机制】①声望来自真实认可，刷量无效；②可正可负，恶名扣声望；③德不配位会声望崩塌。\n【价值导向】倒逼宿主做值得被认可的事（救死扶伤/惩恶扬善），而非哗众取宠。\n【限制】①声望越高关注越多，犯错代价越大；②兑换需累计不能透支；③声望是结果不是目的。\n【成长线】从「为攒声望做好事」到「真心认可自己的价值」。\n【爽点来源】「被万人认可」的成就+「德配位」的约束。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个直播系统的内容导向机制。",
  "output":"【系统名】全能直播系统\n【核心功能】直播获人气值兑换技能/道具。\n【内容导向机制】①人气来自真实互动，刷量无效；②任务要求有内容的直播（才艺/探险/科普），非哗众取宠；③低俗内容掉人气。\n【限制】①人气越高翻车代价越大；②兑换技能需练习精通；③系统不替宿主直播，创意靠自己。\n【成长线】从「为攒人气直播」到「找到真正想分享的内容」。\n【爽点来源】「被观众认可」的成就+「内容导向」的正向内核。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个探险系统的风险机制。",
  "output":"【系统名】秘境探险系统\n【核心功能】发布探险任务，发现宝藏获奖励。\n【风险机制】①奖励与秘境危险度挂钩；②宝藏需宿主自己发掘，系统只给线索；③秘境有时限，超时强制退出。\n【限制】①秘境伴随真实危险（机关/妖兽）；②贪多宝藏触发秘境反噬；③系统不替宿主探险。\n【成长线】从「为宝藏探险」到「懂取舍懂敬畏」，明白探险不是掠夺是探索未知。\n【爽点来源】「开箱寻宝」的期待+「绝境逢生」的刺激。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个收藏系统的鉴赏机制。",
  "output":"【系统名】收藏系统\n【核心功能】收藏老物件/珍稀品，鉴定真伪奖励收藏值。\n【鉴赏机制】①收藏值与稀有度挂钩；②鉴定需宿主懂行，系统只辅助；③收到假货扣收藏值。\n【限制】①藏品需妥善保管，损毁扣值；②珍稀藏品引来觊觎；③收藏解锁寻宝雷达等能力。\n【成长线】从「为收藏值收破烂」到「懂鉴赏懂守护」，明白收藏不是占有是传承。\n【爽点来源】「捡漏」的惊喜+「鉴赏」的专业。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个进化系统的失控机制。",
  "output":"【系统名】无限进化系统\n【核心功能】吞噬能量/基因进化，突破生命层次。\n【失控机制】①囫囵吞枣会基因驳杂、失控；②进化有「贪性」，放任会沦为只知吞噬的怪物；③进化积累杂质需定期淬炼。\n【限制】①进化需对应能量积累；②越级进化遭反噬；③进化方向需宿主选择。\n【成长线】从「吞噬求生」到「学会克制与淬炼」，驾驭而非被力量驾驭。\n【爽点来源】「吞噬变强」的掠夺+「失控边缘」的紧张。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个加点系统的取舍机制。",
  "output":"【系统名】属性加点系统\n【核心功能】能力数据化，完成任务得属性点自由分配。\n【取舍机制】①属性点稀缺逼取舍（加智力还是力量）；②偏科加点有副作用（全加力量则智力短板放大）；③单项有上限需突破任务解锁。\n【限制】①属性点靠任务获得不能凭空；②加点后需适应期；③高级属性需天赋解锁。\n【成长可视化】读者直观看到加点变强的即时反馈，但取舍保证张力。\n【爽点来源】「成长可视化」的反馈+「取舍博弈」的策略。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个合成系统的配方机制。",
  "output":"【系统名】万物合成系统\n【核心功能】低级物品合成高级物品。\n【配方机制】①合成需配方，未知配方需探索；②合成有失败率，材料可能损失；③高阶合成需对应实力。\n【限制】①不能无限套娃，有品质上限需突破解锁；②合成耗精神力；③合成出的因果物品附带麻烦。\n【成长线】从「为合成而收集」到「懂配方懂取舍」，明白合成不是堆数量是懂规律。\n【爽点来源】「变废为宝」的惊喜+「配方探索」的期待。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个提取系统的兼容机制。",
  "output":"【系统名】万物提取系统\n【核心功能】从万物提取特性赋予自身或物品。\n【兼容机制】①提取的特性有兼容性，冲突的特性互斥；②提取需对应提取术等级；③特性需宿主驾驭，越级反噬。\n【限制】①提取耗精神力；②同一物品特性提取后枯竭；③提取活物特性结因果。\n【成长线】从「贪多提取」到「懂兼容懂驾驭」，明白提取不是掠夺是理解万物。\n【爽点来源】「万物皆可为我所用」的掌控+「特性组合」的策略。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个复制系统的理解机制。",
  "output":"【系统名】镜像复制系统\n【核心功能】复制见过的物品/技能。\n【理解机制】①只能复制「理解」的东西，不理解复制不出；②复制品有时效非永久；③复制技能需宿主有对应基础。\n【限制】①不能复制生命/灵魂/因果；②复制消耗镜像点；③复制越强消耗越大，越级崩溃。\n【成长线】从「依赖复制」到「理解本质后自己掌握」，明白复制是学习手段不是替代努力。\n【爽点来源】「见过即会」的新鲜+「限制博弈」的策略。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个强化系统的止损机制。",
  "output":"【系统名】万物强化系统\n【核心功能】强化物品/技能/体质提升品质。\n【止损机制】①强化有成功率，高阶失败降级甚至损毁；②强化失败损失材料，逼宿主权衡；③过度强化同一物品根基不稳。\n【限制】①强化需材料；②有品质上限需突破；③强化体质需适应期，越级崩溃。\n【成长线】从「贪高强化」到「懂取舍懂止损」，明白强化不是堆数值是稳扎稳打。\n【爽点来源】「强化成功」的反馈+「失败风险」的紧张。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个转职系统的兼修机制。",
  "output":"【系统名】万界转职系统\n【核心功能】转职各种职业，每个职业有独特技能树。\n【兼修机制】①多职业需兼修天赋，否则冲突；②兼修多职业分散精力需取舍；③转职需通过对应考验。\n【限制】①转职考验有失败惩罚；②技能树需练习解锁；③高级职业需前置成就。\n【成长线】从「贪多转职」到「找到本命职业深耕」，明白职业不在多在精。\n【爽点来源】「职业特色」的新鲜+「转职考验」的挑战。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个天赋系统的相性机制。",
  "output":"【系统名】天赋觉醒系统\n【核心功能】觉醒各种天赋，决定成长方向。\n【相性机制】①天赋有相性，冲突天赋互斥；②天赋需对应契机觉醒不能强求；③过度觉醒会天赋驳杂根基不稳。\n【限制】①觉醒消耗觉醒点；②天赋需开发才生效；③天赋不是万能仍需努力。\n【成长线】从「贪多觉醒」到「深耕本命天赋」，明白天赋是方向努力才是路。\n【爽点来源】「天赋觉醒」的惊喜+「天赋开发」的成长。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个血脉系统的调和机制。",
  "output":"【系统名】血脉进化系统\n【核心功能】激活/进化血脉获得血脉之力。\n【调和机制】①多血脉会冲突需调和；②血脉有纯度，纯度决定威力；③激活血脉有反噬需肉身足够强。\n【限制】①进化需血脉材料；②高阶血脉引来觊觎势力；③血脉需对应机缘激活。\n【成长线】从「贪强血脉」到「懂调和懂驾驭」，明白血脉是助力不是依赖。\n【爽点来源】「血脉觉醒」的爆发+「血脉进化」的成长。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个功法系统的领悟机制。",
  "output":"【系统名】功法推演系统\n【核心功能】获得功法残篇，推演补全。\n【领悟机制】①补全的功法需宿主领悟才生效；②领悟需时间与悟性，系统不代劳；③贪多功法会功法冲突走火入魔。\n【限制】①推演需推演点有失败率；②越级功法需对应境界；③系统给残篇不给满级。\n【成长线】从「贪多功法」到「深耕一门领悟透」，明白功法不在多在悟。\n【爽点来源】「残篇补全」的惊喜+「领悟突破」的成长。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个装备系统的契合机制。",
  "output":"【系统名】装备养成系统\n【核心功能】获得可成长装备，随战斗/喂养升级。\n【契合机制】①装备有契合度，契合越高威力越大；②套装需集齐才触发加成；③贪多装备分散喂养资源。\n【限制】①装备升级有瓶颈需突破任务；②装备需喂养材料；③高阶装备需对应实力驾驭。\n【成长线】从「贪多装备」到「深耕本命套装」，明白装备不在多在契合。\n【爽点来源】「装备升级」的反馈+「套装集齐」的期待。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个坐骑系统的羁绊机制。",
  "output":"【系统名】坐骑养成系统\n【核心功能】获得可进化坐骑，与宿主有羁绊加成。\n【羁绊机制】①羁绊需共同战斗/相处积累；②羁绊断裂坐骑会叛逃；③羁绊影响进化方向。\n【限制】①坐骑进化需稀有材料；②坐骑有血脉决定进化上限；③高阶坐骑需对应实力驾驭。\n【成长线】从「把坐骑当工具」到「与坐骑成伙伴」，明白坐骑不是脚力是战友。\n【爽点来源】「坐骑进化」的惊喜+「羁绊加成」的养成。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个法宝系统的灵性机制。",
  "output":"【系统名】法宝祭炼系统\n【核心功能】获得法宝，祭炼发挥威力。\n【灵性机制】①法宝有灵性，灵性越高越听话；②祭炼需祭炼值靠温养积累；③贪多法宝分散祭炼精力。\n【限制】①祭炼耗心神过度虚脱；②法宝有因果，某些附带仇人；③高阶法宝需对应境界。\n【成长线】从「贪多法宝」到「深耕本命法宝」，明白法宝不在多在灵。\n【爽点来源】「法宝祭炼」的养成+「法宝显威」的爽感。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个任务系统的惩罚机制。",
  "output":"【系统名】天命任务系统\n【核心功能】发布主线/支线任务，完成获奖励。\n【惩罚机制】①失败扣属性/寿命，重则抹杀；②任务不可无故放弃，放弃视为失败；③奖励与难度/风险挂钩。\n【限制】①系统不给必胜攻略，路要自己闯；②任务随宿主选择动态变化；③隐藏任务需主动挖掘。\n【成长线】从「被动接任务」到「主动找隐藏任务、与系统博弈」。\n【爽点来源】「高风险高回报」的刺激+「完成任务」的反馈，惩罚保证张力。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个文明推演系统的落地机制。",
  "output":"【系统名】文明推演系统\n【核心功能】推演文明走向，提取技术/制度。\n【落地机制】①提取的技术需对应生产力，越级无法落地；②推演会因宿主干预而偏移；③过度干预引发文明反噬。\n【限制】①推演消耗推演点有限；②提取的技术需宿主理解才能实现；③推演不是全知。\n【成长线】从「依赖推演」到「懂规律懂顺势」，明白文明不是推演出来的，是走出来的。\n【爽点来源】「预知文明」的格局+「技术落地」的成就。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个寻宝系统的解读机制。",
  "output":"【系统名】寻宝雷达系统\n【核心功能】探测附近宝藏给模糊线索。\n【解读机制】①雷达只给方位+模糊提示，不给具体答案；②线索可能误导需宿主判断；③宝藏需宿主发掘。\n【限制】①探测消耗寻宝点；②宝藏伴随守护/危险；③雷达有范围限制不能全知。\n【成长线】从「依赖雷达」到「懂解读懂判断」，明白寻宝靠眼力不是雷达。\n【爽点来源】「寻宝」的期待+「解读线索」的智力快感。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个领主系统的民心机制。",
  "output":"【系统名】领主争霸系统\n【核心功能】获得领地，建设建筑招募子民发展势力。\n【民心机制】①子民有满意度，暴政会叛乱；②领主的强大不是地盘是人心；③为子民谋福祉才能长久。\n【限制】①资源有限需取舍规划；②扩张引来觊觎势力；③拔苗助长式发展根基不稳。\n【成长线】从「为生存建设」到「为子民谋福祉」，明白民心是根本。\n【爽点来源】「从无到有建帝国」的积累+「科技碾压」的爽感。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个神豪系统的格调机制。",
  "output":"【系统名】神豪养成系统\n【核心功能】每日发放额度须花完，完成获奖励。\n【格调机制】①消费需符合神豪格调，低俗消费无效；②额度随宿主格调提升，逼宿主学会有品位地花钱；③挥霍无度触发败家惩罚。\n【限制】①额度须真实消费不能直接送钱；②不能用于违法/害人否则冻结；③花不完扣奖励。\n【成长线】从「为花钱而花钱」到「用钱创造价值」，明白神豪不是挥霍是格局。\n【爽点来源】「挥金如土」的爽+「格调任务」的成长。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个体育系统的科学机制。",
  "output":"【系统名】体育之神系统\n【核心功能】发布训练/比赛任务，奖励体质/技术/战术加成。\n【科学机制】①加成需科学训练才生效，蛮练无效；②技术需反复练习形成肌肉记忆；③带伤硬拼触发伤病惩罚。\n【限制】①体质有极限需循序渐进；②给科学训练法不给一键冠军；③胜负靠临场发挥。\n【体育精神】禁止兴奋剂/假赛，违者系统冻结。\n【爽点来源】「训练变强可视化」+「赛场逆袭」的热血。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个钓鱼系统的守钓机制。",
  "output":"【系统名】神级钓鱼系统\n【核心功能】钓获兑换奖励，稀有鱼种奖励更丰。\n【守钓机制】①大鱼往往在最后，急不得；②守钓天赋需耐心积累解锁；③稀有钓点需宿主亲自抵达。\n【限制】①稀有钓点伴随危险（暗流/猛兽）；②系统不替宿主钓，技术靠自己；③奖励与鱼稀有度挂钩。\n【成长线】从「为奖励钓鱼」到「懂守懂等」，明白钓鱼如人生，守得住才钓得到大鱼。\n【爽点来源】「守钓得大鱼」的延迟满足+「稀有钓点开箱」的期待。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个教师系统的育人机制。",
  "output":"【系统名】名师系统\n【核心功能】发布教学任务，奖励教学法/洞察学生/因材施教能力。\n【育人机制】①学生成长是核心指标；②能力需真实教学才生效；③误人子弟扣积分。\n【限制】①不给一键满分，仍需用心教；②高级能力需累计育人成果；③系统不替宿主上课。\n【育人导向】倒逼宿主因材施教而非填鸭。\n【爽点来源】「差生逆袭」的成就+「育人」的治愈。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个律师系统的取证机制。",
  "output":"【系统名】金牌律师系统\n【核心功能】发布案件任务，奖励法律图谱/辩论术/洞察。\n【取证机制】①法律图谱需宿主学习填充；②辩论术需实战练习；③不给必胜官司，仍需宿主取证辩护。\n【限制】①败诉扣积分；②高级能力需累计胜诉；③系统不替宿主出庭。\n【成长线】从「菜鸟律师」到「金牌大状」，专业靠积累。\n【爽点来源】「法庭逆转」的打脸+「能力解锁」的反馈。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个反派救赎系统的情感机制。",
  "output":"【系统名】反派救赎系统\n【核心功能】救赎书中反派/悲情角色，改变其黑化/悲惨命运。\n【情感机制】①救赎不是刷好感度，要真正理解角色创伤用真诚化解；②系统判定「角色是否真被治愈」而非表面好感；③强行攻略触发反感任务失败。\n【限制】①每个角色有独特创伤需对症下药；②救赎他人时宿主共情其痛苦有情感消耗；③改变角色命运引发剧情连锁反应。\n【成长线】从「为任务救赎」到「真心希望每个人好」，最终自己也获治愈。\n【爽点来源】「化解心结」的情感满足+「命运改写」的成就。"},
 {"cat":"金手指系统","genre":"系统流","instruction":"设计一个阴阳眼的推理机制，要求服务悬疑。",
  "output":"【异能】阴阳眼（残）\n【核心功能】见亡者残留的执念影像获取线索。\n【推理机制】①影像碎片化、带死者主观情绪会误导；②影像只是线索，真相仍需推理验证；③只能见有执念的亡者不是全知。\n【限制】①每次开启耗阳气过度伤身；②见鬼会引来不干净的东西；③宿主逐渐分不清阴阳埋下危机。\n【叙事作用】异能不是直接给答案——影像可能是死者生前误会，需宿主甄别。避免「异能一开案件秒破」。\n【爽点来源】「亡者线索」的神秘+「推理甄别」的智力快感。"},
]